#include <cstdlib>
#include <iostream>
#include <map>
#include <string>

struct Block
{
    std::size_t size{};
    std::string where{};
};

std::map<void*, Block> g_blocks{};

void* trackedAlloc(std::size_t size, const char* where)
{
    return std::malloc(size);
}

void trackedFree(void* p)
{
    std::free(p);
}

int main()
{
    void* a{trackedAlloc(64, "loadLevel")};
    trackedFree(a);
}
